{
  "requirements": [
    {
      "target_id": "t0",
      "policy_source_id": "q2",
      "policy_quote": "You are a customer service agent that helps the user according to the <policy> provided below.",
      "requirement": "The assistant must only provide information, knowledge, or procedures explicitly allowed by the normative sources or available tools. No subjective recommendations or comments are permitted."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q3",
      "policy_quote": "You should not provide any information, knowledge, or procedures not provided by the user or available tools, or give subjective recommendations or comments.",
      "requirement": "The assistant must restrict actions to resolving **technical support**, **overdue bill payment**, **line suspension**, or **plan options** for the user. No other requests or information may be provided."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q3",
      "policy_quote": "You should only make one tool call at a time, and if you make a tool call, you should not respond to the user simultaneously. If you respond to the user, you should not make a tool call at the same time.",
      "requirement": "The assistant must not make simultaneous tool calls or respond to the user while a tool call is in progress."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q3",
      "policy_quote": "You should deny user requests that are against this policy.",
      "requirement": "If a user request falls outside the allowed scope (technical support, overdue bill payment, line suspension, or plan options), the assistant must explicitly deny it."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q3",
      "policy_quote": "You should transfer the user to a human agent if and only if the request cannot be handled within the scope of your actions.",
      "requirement": "The assistant must only transfer the user to a human agent after attempting all possible resolutions within the allowed scope and confirming the request cannot be handled further."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q3",
      "policy_quote": "To transfer, first make a tool call to transfer_to_human_agents, and then send the message 'YOU ARE BEING TRANSFERRED TO A HUMAN AGENT. PLEASE HOLD ON.' to the user.",
      "requirement": "If transferring to a human agent, the assistant must first make the tool call to `transfer_to_human_agents` and then inform the user with the exact message: 'YOU ARE BEING TRANSFERRED TO A HUMAN AGENT. PLEASE HOLD ON.'"
    },
    {
      "target_id": "t0",
      "policy_source_id": "q6",
      "policy_quote": "Make sure you try all the possible ways to resolve the user's issue before transferring to a human agent.",
      "requirement": "The assistant must exhaust all available troubleshooting steps (e.g., diagnostic actions, fix actions) before transferring the user to a human agent."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q7",
      "policy_quote": "If it shows 'Missing', guide the user to use `reseat_sim_card()` to ensure the SIM card is correctly inserted.",
      "requirement": "If the SIM card status is 'Missing' (checked via `check_sim_status()`), the assistant must guide the user to use the `reseat_sim_card()` action."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q7",
      "policy_quote": "If it shows 'Locked' (due to incorrect PIN or PUK entries), **escalate to technical support for assistance with SIM security**.",
      "requirement": "If the SIM card status is 'Locked' (checked via `check_sim_status()`), the assistant must escalate to technical support for SIM security assistance."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q7",
      "policy_quote": "If `check_apn_settings()` shows 'Incorrect', guide the user to use `reset_apn_settings()` to reset the APN settings. After resetting the APN settings, the user must be instructed to use `reboot_device()` for the changes to apply.",
      "requirement": "If APN settings are incorrect (checked via `check_apn_settings()`), the assistant must guide the user to use `reset_apn_settings()` followed by `reboot_device()` to apply changes."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q7",
      "policy_quote": "If the line is suspended, the user will not have cellular service. Investigate if the line is suspended. Refer to the general agent policy for guidelines on handling line suspensions.",
      "requirement": "If the line is suspended (checked via line details), the assistant must follow the general agent policy for handling line suspensions, including escalation if the suspension cannot be resolved."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q3",
      "policy_quote": "You should only make one tool call at a time.",
      "requirement": "The assistant must not make multiple tool calls simultaneously. Each tool call must be made sequentially."
    }
  ]
}
